#include <algorithm>
#include <cstdio>
#include <vector>

using namespace std;

int main() {
    int n, c;
    scanf("%d %d", &n, &c);

    vector<int> scores(n), times(n);

    for (int i = 0; i < n; ++i) {
        scanf("%d", &scores[i]);
    }
    for (int i = 0; i < n; ++i) {
        scanf("%d", &times[i]);
    }

    int lscore = 0, rscore = 0;
    int ltime = 0, rtime = 0;

    for (int i = 0; i < n; ++i) {
        ltime += times[i];
        lscore += max(scores[i] - ltime * c, 0);

        int j = n - 1 - i;
        rtime += times[j];
        rscore += max(scores[j] - rtime * c, 0);
    }

    printf("%s\n", lscore == rscore ? "Tie" :
                    lscore > rscore ? "Limak" : "Radewoosh");

    return 0;
}

